import ast,sys,glob
for f in glob.glob('pelican/**/*.py',recursive=True):
    if '/tests/' in f: continue
    src=open(f).read(); t=ast.parse(src)
    names=set()
    for n in ast.walk(t):
        if isinstance(n,(ast.Import,ast.ImportFrom)) and n.col_offset==0:
            for a in n.names:
                names.add((a.asname or a.name).split('.')[0])
    used={n.id for n in ast.walk(t) if isinstance(n,ast.Name)}|{n.value.id for n in ast.walk(t) if isinstance(n,ast.Attribute) and isinstance(n.value,ast.Name)}
    for nm in names-used:
        print(f,nm)
EOF
